import{c as d,Q as r,j as a,m as e}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"职业选择推荐","description":"RO3 全职业分析，帮你快速找到最适合的职业","frontmatter":{"title":"职业选择推荐","description":"RO3 全职业分析，帮你快速找到最适合的职业","lastUpdated":true},"headers":[],"relativePath":"guide/job-pick.md","filePath":"guide/job-pick.md","lastUpdated":1779362930000}'),h={name:"guide/job-pick.md"};function o(n,t,l,i,s,b){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="职业选择推荐" tabindex="-1">职业选择推荐 <a class="header-anchor" href="#职业选择推荐" aria-label="Permalink to &quot;职业选择推荐&quot;">​</a></h1><p>选对职业决定了你的 RO3 体验。本文根据 <strong>氪金程度、操作要求、游戏目标</strong> 三个维度帮你找到最适合的职业。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>推荐职业</th></tr></thead><tbody><tr><td>零氪 / 新手</td><td>剑士</td></tr><tr><td>零氪 / 喜欢组队</td><td>牧师</td></tr><tr><td>微氪 / 追求伤害</td><td>法师</td></tr><tr><td>操作党 / 搬砖</td><td>刺客</td></tr><tr><td>上班族 / 挂机</td><td>弓箭手</td></tr><tr><td>经济型 / 副号</td><td>商人</td></tr></tbody></table><h2 id="详细对比" tabindex="-1">详细对比 <a class="header-anchor" href="#详细对比" aria-label="Permalink to &quot;详细对比&quot;">​</a></h2><h3 id="剑士-⭐⭐⭐⭐⭐" tabindex="-1">剑士 ⭐⭐⭐⭐⭐ <a class="header-anchor" href="#剑士-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;剑士 ⭐⭐⭐⭐⭐&quot;">​</a></h3><p><strong>定位：坦克 / 近战物理</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>开荒强度</td><td>S</td><td>能抗能打，最稳的开荒选择</td></tr><tr><td>操作难度</td><td>★☆☆☆☆</td><td>简单粗暴，适合新手</td></tr><tr><td>零氪友好度</td><td>★★★★★</td><td>不需要强装备也能玩</td></tr><tr><td>组队需求</td><td>★★★★★</td><td>坦克永远缺</td></tr><tr><td>搬砖能力</td><td>★★★☆☆</td><td>中等，打材料效率一般</td></tr><tr><td>PVP 强度</td><td>A</td><td>GVG 核心前排</td></tr></tbody></table><p><strong>适合玩家</strong>：第一次玩 RO 系列的新手、零氪玩家、喜欢抗伤冲前排的玩家</p><h3 id="法师-⭐⭐⭐⭐" tabindex="-1">法师 ⭐⭐⭐⭐ <a class="header-anchor" href="#法师-⭐⭐⭐⭐" aria-label="Permalink to &quot;法师 ⭐⭐⭐⭐&quot;">​</a></h3><p><strong>定位：远程魔法爆发</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>开荒强度</td><td>A</td><td>群怪效率高，单体略弱</td></tr><tr><td>操作难度</td><td>★★★☆☆</td><td>需要走位和技能循环</td></tr><tr><td>零氪友好度</td><td>★★★☆☆</td><td>需要一定装备支撑</td></tr><tr><td>组队需求</td><td>★★★★☆</td><td>群怪输出热门职业</td></tr><tr><td>搬砖能力</td><td>★★☆☆☆</td><td>耗蓝高，不适合长期挂机</td></tr><tr><td>PVP 强度</td><td>S</td><td>爆发伤害极高</td></tr></tbody></table><p><strong>适合玩家</strong>：喜欢爆发伤害、不介意操作、愿意微氪的玩家</p><h3 id="刺客-⭐⭐⭐⭐" tabindex="-1">刺客 ⭐⭐⭐⭐ <a class="header-anchor" href="#刺客-⭐⭐⭐⭐" aria-label="Permalink to &quot;刺客 ⭐⭐⭐⭐&quot;">​</a></h3><p><strong>定位：近战物理爆发</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>开荒强度</td><td>B</td><td>前期较弱，后期起飞</td></tr><tr><td>操作难度</td><td>★★★★☆</td><td>需要背刺操作和走位</td></tr><tr><td>零氪友好度</td><td>★★★☆☆</td><td>装备好才能打出伤害</td></tr><tr><td>组队需求</td><td>★★☆☆☆</td><td>偏单刷职业</td></tr><tr><td>搬砖能力</td><td>★★★★★</td><td>打金效率全职业第一</td></tr><tr><td>PVP 强度</td><td>S</td><td>秒杀后排</td></tr></tbody></table><p><strong>适合玩家</strong>：操作党、搬砖党、喜欢高暴击数字的玩家</p><h3 id="牧师-⭐⭐⭐⭐" tabindex="-1">牧师 ⭐⭐⭐⭐ <a class="header-anchor" href="#牧师-⭐⭐⭐⭐" aria-label="Permalink to &quot;牧师 ⭐⭐⭐⭐&quot;">​</a></h3><p><strong>定位：治疗 / 辅助</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>开荒强度</td><td>B</td><td>单练慢，组队起飞</td></tr><tr><td>操作难度</td><td>★★☆☆☆</td><td>只要加血和 buff</td></tr><tr><td>零氪友好度</td><td>★★★★★</td><td>不需要输出装备</td></tr><tr><td>组队需求</td><td>★★★★★</td><td>永远缺牧师</td></tr><tr><td>搬砖能力</td><td>★★☆☆☆</td><td>可以带小号收费</td></tr><tr><td>PVP 强度</td><td>A</td><td>团队核心辅助</td></tr></tbody></table><p><strong>适合玩家</strong>：零氪玩家、社交型玩家、喜欢辅助的玩家</p><h3 id="弓箭手-⭐⭐⭐" tabindex="-1">弓箭手 ⭐⭐⭐ <a class="header-anchor" href="#弓箭手-⭐⭐⭐" aria-label="Permalink to &quot;弓箭手 ⭐⭐⭐&quot;">​</a></h3><p><strong>定位：远程物理持续输出</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>开荒强度</td><td>B</td><td>远程安全但伤害一般</td></tr><tr><td>操作难度</td><td>★★☆☆☆</td><td>放风筝即可</td></tr><tr><td>零氪友好度</td><td>★★★★☆</td><td>低耗蓝，省钱</td></tr><tr><td>组队需求</td><td>★★★☆☆</td><td>输出位，竞争较多</td></tr><tr><td>搬砖能力</td><td>★★★☆☆</td><td>挂机省心，效率中等</td></tr><tr><td>PVP 强度</td><td>B</td><td>需要装备支撑</td></tr></tbody></table><p><strong>适合玩家</strong>：上班族挂机党、多开玩家、喜欢远程安全的玩家</p><h3 id="商人-⭐⭐⭐" tabindex="-1">商人 ⭐⭐⭐ <a class="header-anchor" href="#商人-⭐⭐⭐" aria-label="Permalink to &quot;商人 ⭐⭐⭐&quot;">​</a></h3><p><strong>定位：经济 / 制造</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>开荒强度</td><td>C</td><td>输出低，练级慢</td></tr><tr><td>操作难度</td><td>★★☆☆☆</td><td>简单但效率低</td></tr><tr><td>零氪友好度</td><td>★★★★☆</td><td>能赚钱所以好发育</td></tr><tr><td>组队需求</td><td>★★☆☆☆</td><td>组队混经验位</td></tr><tr><td>搬砖能力</td><td>★★★★★</td><td>最强赚钱职业</td></tr><tr><td>PVP 强度</td><td>C</td><td>铁匠 PVP 一般</td></tr></tbody></table><p><strong>适合玩家</strong>：经济学爱好者、副号玩家、想做装备生意的玩家</p><h2 id="职业组合推荐" tabindex="-1">职业组合推荐 <a class="header-anchor" href="#职业组合推荐" aria-label="Permalink to &quot;职业组合推荐&quot;">​</a></h2><h3 id="主号-副号搭配" tabindex="-1">主号 + 副号搭配 <a class="header-anchor" href="#主号-副号搭配" aria-label="Permalink to &quot;主号 + 副号搭配&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主号</th><th>副号</th><th>理由</th></tr></thead><tbody><tr><td>剑士</td><td>商人</td><td>剑士打材料，商人制作和出售</td></tr><tr><td>法师</td><td>牧师</td><td>法师输出 + 牧师自奶，双开刷本</td></tr><tr><td>刺客</td><td>弓箭手</td><td>刺客搬砖 + 弓箭手挂机双开</td></tr></tbody></table><h3 id="固定队推荐配置" tabindex="-1">固定队推荐配置 <a class="header-anchor" href="#固定队推荐配置" aria-label="Permalink to &quot;固定队推荐配置&quot;">​</a></h3><ul><li><strong>1 坦克</strong>（剑士）</li><li><strong>1 治疗</strong>（牧师）</li><li><strong>2 输出</strong>（法师 + 刺客/弓箭手）</li><li><strong>1 辅助</strong>（商人提供补给）</li></ul>',34)])])}const g=d(h,[["render",o]]);export{c as __pageData,g as default};
